const [files, setFiles] = useState([]);
const zoneRef = useRef(null);

async function upload(file, onProgress, { signal }) {
  const { url } = await putToStorage(file, { onProgress, signal }); // reject with new Error("…") to show it on the row
  return url;                                                       // lands on the item as `result`
}

<button onClick={() => zoneRef.current.click()}>Choose a file</button>

<FileDropzone
  ref={zoneRef}
  label="Receipt photo or PDF"
  accept=".jpg,.jpeg,.png,.pdf"
  maxSizeMB={15}
  maxFiles={10}
  value={files}
  onChange={setFiles}
  onRemove={(item) => deleteFromStorage(item.result)}
  upload={upload}
  fullWidth
/>

// one file the row can replace or remove, starting from a stored logo
const [logoFiles, setLogoFiles] = useState(logo ? [{ id: "logo", name: logo.name, status: "done", preview: logo.url, result: logo.url }] : []);

<FileDropzone
  label="Logo"
  accept=".png,.jpg,.svg"
  maxSizeMB={2}
  multiple={false}
  hideZoneWhenFull
  height={132}
  value={logoFiles}
  onChange={(items) => {
    setLogoFiles(items);
    const done = items.find((i) => i.status === "done");
    setLogo(done ? { name: done.name, url: done.result } : null);
  }}
  upload={uploadLogo}
/>
